491	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
492	        ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
493	        validateRequiredFields(ownerFieldsDto);
494	        LocalDate registrationDate = ownerFieldsDto.getRegistrationDate();
495	        if (registrationDate == null) {
496	            registrationDate = LocalDate.now();
497	        }
498	        registrationDate = toBusinessDay(registrationDate);
499	        ownerFieldsDto.setRegistrationDate(registrationDate);
500	        rejectDailyOwnerLimit(registrationDate);
501	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
502	            rejectDuplicateHousehold(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
503	        }
504	        rejectCityAtCapacity(ownerFieldsDto.getCity());
505	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
506	        rejectDuplicateTelephone(normalizedTelephone);
507	        ownerFieldsDto.setTelephone(normalizedTelephone);
508	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
509	        HttpHeaders headers = new HttpHeaders();
510	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
511	        owner.setCustomerCode(nextCustomerCode(ownerFieldsDto.getCity(), ownerFieldsDto.getLastName()));
512	        String ownerHouseholdId = householdId(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
513	        owner.setHouseholdId(ownerHouseholdId);
514	        owner.setHouseholdSize(householdSize(ownerHouseholdId));
515	        owner.setNamesakeCount(countNamesakes(ownerFieldsDto.getFirstName(), ownerFieldsDto.getLastName()));
516	        owner.setBulkSignupWarning(bulkSignupWarning(registrationDate));
517	        this.clinicService.saveOwner(owner);
518	        AUDIT.info("owner created id={} customerCode={} registrationDate={}",
519	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
520	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
